const $=s=>document.querySelector(s);
const escapeHTML=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeImage=s=>{try{const u=new URL(s,location.origin);return u.protocol==='https:'||u.origin===location.origin?escapeHTML(u.href):''}catch{return ''}};
let products=[
{id:'duck',title:'The duck vest',category:'Crochet',images:['/assets/item-front.jpg','/assets/item-back.jpg'],description:'An olive-green crochet vest with a duck motif, bright blue edging, and a checkerboard surprise on the back.'},
{id:'orange',title:'The statement sweater',category:'Crochet',images:['/assets/crochet6.jpg'],description:'Warm orange, bold checkerboard sleeves, and a playful graphic. A little wearable personality.'},
{id:'hood',title:'The colorful hood',category:'Crochet',images:['/assets/crochet2.jpg'],description:'A colorful crochet hood with a tie detail and plenty of texture.'},
{id:'stripe',title:'The everyday vest',category:'Crochet',images:['/assets/vest.jpg'],description:'An earthy striped vest with a relaxed shape. Made for layering and everyday adventures.'},
{id:'cherry',title:'Cherry on top',category:'Art',images:['/assets/cherries.jpg'],description:'A peek inside the sketchbook: flaming cherries, checkerboard details, and bold hand-carved texture.'},
{id:'mermaid',title:'A little out of water',category:'Art',images:['/assets/mermaid.jpg'],description:'A mermaid with a checkerboard tail. A glimpse into the world of Yarn Hooker’s artwork.'}
];
let live=false,filter='All',cart=[];
try{cart=JSON.parse(localStorage.getItem('yh-bag')||'[]');if(!Array.isArray(cart))cart=[];cart=cart.filter(x=>typeof x.id==='string'&&Number.isInteger(x.quantity)&&x.quantity>0&&x.quantity<100)}catch{cart=[]}
const money=p=>p.price?new Intl.NumberFormat(undefined,{style:'currency',currency:p.currency}).format(Number(p.price)):'Collection preview';
function render(){const shown=products.filter(p=>filter==='All'||p.category===filter);$('#products').innerHTML=shown.map(p=>`<article class="product"><div class="product-image ${p.images[1]?'has-back':''}"><button class="view" data-product="${escapeHTML(p.id)}" aria-label="View ${escapeHTML(p.title)}"><img src="${safeImage(p.images[0])}" alt="${escapeHTML(p.title)} — front" loading="lazy">${p.images[1]?`<img class="back" src="${safeImage(p.images[1])}" alt="${escapeHTML(p.title)} — alternate view" loading="lazy">`:''}</button><span class="badge">${live?escapeHTML(p.category.toUpperCase()):'FROM THE STUDIO'}</span>${p.images[1]?'<button class="flip" aria-pressed="false">Front / back ↻</button>':''}</div><div class="product-meta"><button data-product="${escapeHTML(p.id)}">${escapeHTML(p.title)}<small>${escapeHTML(money(p))}</small></button><span class="arrow">↗</span></div></article>`).join('')||'<p>No pieces in this category yet. Explore all the things.</p>';}
function sync(){try{localStorage.setItem('yh-bag',JSON.stringify(cart))}catch{}$('#count').textContent=cart.reduce((n,x)=>n+x.quantity,0)}
function openProduct(id){const p=products.find(p=>p.id===id);if(!p)return;$('#product-detail').innerHTML=`<div><img id="detail-image" src="${safeImage(p.images[0])}" alt="${escapeHTML(p.title)}">${p.images[1]?`<div class="thumbs">${p.images.map((src,i)=>`<button data-image="${safeImage(src)}">${i===0?'Front':'Back / alternate'}</button>`).join('')}</div>`:''}</div><div><div class="eyebrow">${escapeHTML(p.category)}</div><h2>${escapeHTML(p.title)}</h2><p>${escapeHTML(p.description)}</p><p>${escapeHTML(money(p))}</p>${live?`<label>Choose an option<select id="variant">${p.variants.map(v=>`<option value="${escapeHTML(v.id)}" ${v.availableForSale?'':'disabled'}>${escapeHTML(v.title)}${v.availableForSale?'':' — sold out'}</option>`).join('')}</select></label>`:'<p>Preview piece. Sizing, materials, pricing, and availability will be confirmed at launch.</p>'}<button class="button" id="add" ${live&&!p.variants.some(v=>v.availableForSale)?'disabled':''}>${live?'Add to bag':'Save to preview bag'} +</button><p id="added" role="status"></p></div>`;$('#add').onclick=()=>{const variant=live?$('#variant').value:'preview';const key=p.id+'|'+variant;const row=cart.find(x=>x.id===key);if(row){row.quantity=Math.min(99,row.quantity+1)}else{cart.push({id:key,productId:p.id,variant,quantity:1,title:p.title,image:p.images[0],price:p.price,currency:p.currency})}sync();$('#added').textContent=live?'Added to your bag.':'Saved. Preview items cannot be purchased yet.'};$('#product-dialog').showModal()}
function showBag(){const active=cart.filter(x=>live?x.variant!=='preview':x.variant==='preview');$('#bag-items').innerHTML=active.length?active.map(x=>`<div class="bag-row"><img src="${safeImage(x.image)}" alt="${escapeHTML(x.title)}"><div><strong>${escapeHTML(x.title)}</strong><p>Quantity: ${x.quantity}</p><button data-remove="${escapeHTML(x.id)}">Remove</button></div></div>`).join(''):'<p>Your bag is waiting for a favorite thing.</p>';$('#bag-note').textContent=live?'Final prices, shipping, and taxes are shown at Shopify checkout.':'This is a preview bag. No payment or order will be taken.';$('#checkout').disabled=!live||!active.length;$('#checkout').textContent=live?'Continue to checkout ↗':'Shop opening soon';$('#checkout-status').textContent='';if(!$('#bag-dialog').open)$('#bag-dialog').showModal()}
document.addEventListener('click',e=>{const close=e.target.closest('.close');if(close)close.closest('dialog').close();const product=e.target.closest('[data-product]');if(product)openProduct(product.dataset.product);const flip=e.target.closest('.flip');if(flip){const state=flip.closest('.product-image').classList.toggle('flipped');flip.setAttribute('aria-pressed',String(state))}const tab=e.target.closest('[data-filter]');if(tab){filter=tab.dataset.filter;document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('active',b===tab));render()}const thumb=e.target.closest('[data-image]');if(thumb)$('#detail-image').src=thumb.dataset.image;const remove=e.target.closest('[data-remove]');if(remove){cart=cart.filter(x=>x.id!==remove.dataset.remove);sync();showBag()}});
$('#bag').onclick=showBag;$('#year').textContent=new Date().getFullYear();$('#custom-open').onclick=()=>{$('#custom-dialog').showModal();try{$('#brief').value=localStorage.getItem('yh-brief')||''}catch{}};$('#brief-form').onsubmit=e=>{e.preventDefault();try{localStorage.setItem('yh-brief',$('#brief').value);$('#brief-status').textContent='Saved on this device. You can return to your idea here anytime.'}catch{$('#brief-status').textContent='Your browser could not save this idea. Copy it somewhere safe.'}};
async function api(query,variables={}){const c=window.SHOPIFY_CONFIG;if(!/^[a-z0-9][a-z0-9-]*\.myshopify\.com$/.test(c.domain))throw Error('Invalid Shopify domain');const r=await fetch(`https://${c.domain}/api/${c.apiVersion}/graphql.json`,{method:'POST',headers:{'Content-Type':'application/json','X-Shopify-Storefront-Access-Token':c.publicAccessToken},body:JSON.stringify({query,variables})});if(!r.ok)throw Error('The shop could not be reached. Please try again.');const j=await r.json();if(j.errors)throw Error('The shop could not complete this request.');return j.data}
$('#checkout').onclick=async()=>{const b=$('#checkout');b.disabled=true;$('#checkout-status').textContent='Opening secure checkout…';try{const lines=cart.filter(x=>x.variant!=='preview').map(x=>({merchandiseId:x.variant,quantity:x.quantity}));const data=await api('mutation Cart($input: CartInput!) { cartCreate(input:$input) { cart { checkoutUrl } userErrors { message } } }',{input:{lines}});if(data.cartCreate.userErrors.length)throw Error(data.cartCreate.userErrors.map(x=>x.message).join(' '));const url=new URL(data.cartCreate.cart.checkoutUrl);if(url.protocol!=='https:')throw Error('Invalid checkout URL');location.assign(url.href)}catch(e){$('#checkout-status').textContent=e.message;b.disabled=false}};
async function loadShop(){const c=window.SHOPIFY_CONFIG;if(!c?.domain||!c.publicAccessToken)return;try{const d=await api('{ products(first:100) { nodes { id title description productType images(first:8) { nodes { url } } variants(first:100) { nodes { id title availableForSale price { amount currencyCode } } } } } }');products=d.products.nodes.filter(p=>p.images.nodes.length&&p.variants.nodes.length).map(p=>({id:p.id,title:p.title,description:p.description,category:/crochet|knit|wear/i.test(p.productType)?'Crochet':'Art',images:p.images.nodes.map(i=>i.url),variants:p.variants.nodes,price:p.variants.nodes[0].price.amount,currency:p.variants.nodes[0].price.currencyCode}));live=true;$('#catalog-note').textContent='Explore the latest from Yarn Hooker.';render()}catch{$('#catalog-status').textContent='The live shop is temporarily unavailable. You’re viewing the studio collection; checkout is paused.'}}
render();sync();loadShop();
